from __future__ import annotations

import base64
import gzip
import re
import shutil
from pathlib import Path

UNIFIED = ""
STAGES_PARTS = (
    "",
    "",
    "",
    "",
    "",
)

FILES = {
    "src/fabric_data_framework/certification/unified.py": UNIFIED,
    "src/fabric_data_framework/certification/unified_stages.py": "".join(STAGES_PARTS),
}
for raw_path, encoded in FILES.items():
    path = Path(raw_path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(gzip.decompress(base64.b64decode(encoded)))

for path in Path("src").rglob("*.py"):
    text = path.read_text(encoding="utf-8")
    text = re.sub(
        r"from\s+\.+safety\s+import",
        "from fabric_data_framework.contracts.audit_safety import",
        text,
    )
    text = text.replace(
        "fabric_data_framework.evidence.safety",
        "fabric_data_framework.contracts.audit_safety",
    )
    path.write_text(text, encoding="utf-8")

projection = Path("src/fabric_data_framework/adapters/fabric/current_projection.py")
text = projection.read_text(encoding="utf-8")
text = text.replace(
    "class _ProjectionMutationOutcome:\n    affected_keys: int\n    mutations: MutationCounts\n",
    "class _ProjectionMutationOutcome:\n    affected_keys: int\n    mutations: MutationCounts\n    rebuilt: bool = False\n",
)
text = text.replace(
    "    reconcile: SparkProjectionReconciliation | None,\n    *,\n    rebuilt: bool = False,\n) -> CurrentProjectionExecutionResult:\n",
    "    reconcile: SparkProjectionReconciliation | None,\n) -> CurrentProjectionExecutionResult:\n",
)
text = text.replace("        rebuilt=rebuilt,\n", "        rebuilt=outcome.rebuilt,\n")
text = text.replace(
    "            outcome = _ProjectionMutationOutcome(\n                affected_keys=row_count,\n                mutations=MutationCounts(inserted=row_count),\n            )\n",
    "            outcome = _ProjectionMutationOutcome(\n                affected_keys=row_count,\n                mutations=MutationCounts(inserted=row_count),\n                rebuilt=True,\n            )\n",
)
text = text.replace(
    "                outcome,\n                reconcile,\n                rebuilt=True,\n            )\n",
    "                outcome,\n                reconcile,\n            )\n",
)
projection.write_text(text, encoding="utf-8")

if Path("src/fabric_data_framework.egg-info").exists():
    shutil.rmtree("src/fabric_data_framework.egg-info")
for root in (Path("src"), Path("tests")):
    for path in list(root.rglob("__pycache__")):
        shutil.rmtree(path, ignore_errors=True)
    for path in root.rglob("*.pyc"):
        path.unlink(missing_ok=True)
for raw_path in (
    ".github/workflows/apply-unified-refactor.yml",
    "tools/apply_unified_refactor.py",
):
    Path(raw_path).unlink(missing_ok=True)
